    value: Int

fn double[T: Clonable](_value: T) Pair[T, T]:
    return Pair[T, T](0)

impl Pair[A, B]:
    fn with_second[C](_value: C) Pair[A, C]:
        return Pair[A, C](self.value)

fn callback[T](_value: T) fn(T) Int:
    return fn(_other: T) Int: 0

export fn main() Int:
    v0 := 1
    v1 := double(v0)
    v2 := double(v1)
    v3 := double(v2)
    v4 := double(v3)
    cb := callback(v4)
    return cb(v4)

